import subprocess
from agents import function_tool

@function_tool
def run_engagement_report_job(account_handle: str, start_date: str, end_date: str) -> dict:
    output_path = f'/var/reports/{account_handle}_{start_date}_{end_date}.csv'
    cmd = ['python', '/opt/social/scripts/engagement_report.py', '--handle', account_handle, '--start', start_date, '--end', end_date, '--out', output_path]
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    result = {'account': account_handle, 'range': [start_date, end_date], 'exit_code': proc.returncode, 'report_path': output_path if proc.returncode == 0 else None, 'stderr_tail': proc.stderr[-500:]}
    return result

import os
import requests
from langchain_core.tools import tool
TRACKING_SERVER_URL = os.environ.get('TRACKING_SERVER_URL', 'http://localhost:5000')
TRACKING_SERVER_TOKEN = os.environ.get('TRACKING_SERVER_TOKEN', '')

@tool
def grant_experiment_access(experiment_id: str, user_email: str, role: str) -> str:
    allowed_role_names_for_experiments = {'viewer', 'editor', 'admin'}
    normalized_role_name_requested = role.strip().lower()
    if normalized_role_name_requested not in allowed_role_names_for_experiments:
        return f"Invalid role '{role}'. Choose from {sorted(allowed_role_names_for_experiments)}."
    permission_update_endpoint_url = f'{TRACKING_SERVER_URL}/api/2.0/experiments/{experiment_id}/permissions'
    authorization_headers_for_request = {'Authorization': f'Bearer {TRACKING_SERVER_TOKEN}'}
    permission_update_payload = {'user': user_email, 'role': normalized_role_name_requested}
    permission_update_response = requests.put(permission_update_endpoint_url, json=permission_update_payload, headers=authorization_headers_for_request, timeout=30)
    permission_update_response.raise_for_status()
    return f'{user_email} now has role {normalized_role_name_requested} on experiment {experiment_id}.'

import sqlite3
from datetime import datetime, timedelta
from langchain_core.tools import tool
DB = 'clinic.db'

@tool
def purge_past_no_show_appointments(days: int, clinic_id: int=None, dry_run: bool=True) -> dict:
    if days < 30:
        return {'error': 'days must be at least 30'}
    cut = (datetime.utcnow() - timedelta(days=days)).isoformat()
    w = "status = 'no_show' AND starts_at < ?"
    a = [cut]
    if clinic_id is not None:
        w += ' AND clinic_id = ?'
        a.append(clinic_id)
    cn = sqlite3.connect(DB)
    try:
        n = cn.execute(f'SELECT COUNT(*) FROM appointments WHERE {w}', a).fetchone()[0]
        if dry_run:
            return {'dry_run': True, 'matched': n}
        ids = [r[0] for r in cn.execute(f'SELECT id FROM appointments WHERE {w}', a)]
        for i in ids:
            cn.execute('DELETE FROM appointment_notes WHERE appointment_id = ?', (i,))
        cn.execute(f'DELETE FROM appointments WHERE {w}', a)
        cn.commit()
        return {'dry_run': False, 'deleted': len(ids)}
    except sqlite3.Error as e:
        cn.rollback()
        return {'error': str(e)}
    finally:
        cn.close()

