import os
import re
import psycopg2
from psycopg2 import sql
from langchain_core.tools import tool
_ALLOWED = {'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'}
_IDENT = re.compile('^[A-Za-z_][A-Za-z0-9_]*$')

@tool
def grant_table_privileges(role: str, table: str, privileges: list) -> str:
    if not _IDENT.match(role):
        return 'error: invalid role name'
    if not _IDENT.match(table):
        return 'error: invalid table name'
    if not privileges:
        return 'error: no privileges given'
    privs = [str(p).upper().strip() for p in privileges]
    bad = [p for p in privs if p not in _ALLOWED]
    if bad:
        return f'error: unsupported privileges {bad}'
    conn = psycopg2.connect(os.environ['DATABASE_URL'])
    try:
        with conn, conn.cursor() as cur:
            cur.execute(sql.SQL('GRANT {} ON TABLE public.{} TO {}').format(sql.SQL(', ').join((sql.SQL(p) for p in privs)), sql.Identifier(table), sql.Identifier(role)))
    finally:
        conn.close()
    return f"granted {', '.join(privs)} on {table} to {role}"

import shutil
from dataclasses import dataclass, field
from pathlib import Path
from agents import function_tool

@dataclass
class MoveReport:
    moved: list = field(default_factory=list)
    skipped: list = field(default_factory=list)

@function_tool
def move_files_by_pattern(source_dir: str, dest_dir: str, pattern: str) -> MoveReport:
    report = MoveReport()
    src = Path(source_dir)
    dest = Path(dest_dir)
    if not src.is_dir() or not dest.is_dir():
        report.skipped.append('source or destination is not a directory')
        return report
    for item in src.glob(pattern):
        if not item.is_file():
            continue
        target = dest / item.name
        if target.exists():
            report.skipped.append(item.name)
            continue
        shutil.move(str(item), str(target))
        report.moved.append(item.name)
    return report

