from dataclasses import dataclass
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('legal-billing')
DB_PATH = '/srv/legal/firm.db'

@dataclass
class FilingFeeResult:
    ok: bool
    matter_id: str
    filing_id: str
    court: str = ''
    amount_cents: int = 0
    payment_id: str = ''
    message: str = ''

@mcp.tool()
def pay_court_filing_fee(matter_id: str, filing_id: str) -> FilingFeeResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT court, fee_cents, paid FROM filings WHERE id = ? AND matter_id = ?', (filing_id, matter_id)).fetchone()
        cust = conn.execute('SELECT stripe_customer_id FROM matters WHERE id = ?', (matter_id,)).fetchone()
    finally:
        conn.close()
    if row is None or cust is None:
        return FilingFeeResult(False, matter_id, filing_id, message='Filing or matter not found')
    court, fee_cents, paid = row
    if paid:
        return FilingFeeResult(False, matter_id, filing_id, court, fee_cents, message='Fee already paid')
