import sqlite3
from datetime import datetime
DATABASE_PATH = '/var/data/analytics.db'
VALID_FREQUENCIES = ('daily', 'weekly', 'monthly')
VALID_FORMATS = ('pdf', 'csv', 'html')

def _build_update_fields(frequency, delivery_format, is_active):
    fields = {}
    if frequency is not None:
        if frequency not in VALID_FREQUENCIES:
            raise ValueError(f'Unsupported frequency: {frequency}')
        fields['frequency'] = frequency
    if delivery_format is not None:
        if delivery_format not in VALID_FORMATS:
            raise ValueError(f'Unsupported format: {delivery_format}')
        fields['delivery_format'] = delivery_format
    if is_active is not None:
        fields['is_active'] = 1 if is_active else 0
    return fields

def update_report_schedule_settings(schedule_id, frequency=None, delivery_format=None, is_active=None):
    fields = _build_update_fields(frequency, delivery_format, is_active)
    if not fields:
        return {'updated': False, 'reason': 'no changes supplied'}
    fields['updated_at'] = datetime.utcnow().isoformat()
    assignments = ', '.join((f'{column} = ?' for column in fields))
    values = list(fields.values()) + [schedule_id]
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        cursor = connection.execute(f'UPDATE report_schedules SET {assignments} WHERE id = ?', values)
        connection.commit()
        changed = cursor.rowcount
    finally:
        connection.close()
    if changed == 0:
        return {'updated': False, 'reason': 'schedule not found'}
    return {'updated': True, 'schedule_id': schedule_id, 'fields': list(fields.keys())}

import sqlite3
import subprocess
from agents import function_tool
_DATABASE_PATH = '/var/data/recruiting.db'
_PROVISIONING_SCRIPT_PATH = '/opt/hr/scripts/provision_new_hire.sh'
_ALLOWED_ROLES = {'engineer', 'sales_rep', 'recruiter', 'analyst', 'designer'}

@function_tool
def run_onboarding_provisioning_for_hire(candidate_id: int, access_role: str) -> str:
    if access_role not in _ALLOWED_ROLES:
        return 'Role not allowed: ' + access_role
    database_connection = sqlite3.connect(_DATABASE_PATH)
    try:
        candidate_row_from_database = database_connection.execute('SELECT work_email, offer_status FROM candidates WHERE id = ?', (candidate_id,)).fetchone()
        if candidate_row_from_database is None:
            return 'Candidate not found'
        candidate_work_email_address, current_offer_status = candidate_row_from_database
        if current_offer_status != 'accepted':
            return 'Offer has not been accepted'
        provisioning_process_result = subprocess.run([_PROVISIONING_SCRIPT_PATH, candidate_work_email_address, access_role], capture_output=True, text=True, timeout=120)
        if provisioning_process_result.returncode != 0:
            return 'Provisioning failed: ' + provisioning_process_result.stderr.strip()
        database_connection.execute('INSERT INTO role_grants (candidate_id, role_name) VALUES (?, ?)', (candidate_id, access_role))
        database_connection.commit()
    finally:
        database_connection.close()
    return 'Provisioned ' + candidate_work_email_address + ' with role ' + access_role

