import subprocess
from dataclasses import dataclass
from agents import function_tool

@dataclass
class ReportResult:
    restaurant_id: str
    exit_code: int
    report_path: str
    stderr: str

@function_tool
def run_nightly_table_turnover_report(restaurant_id: str, service_date: str) -> ReportResult:
