import stripe
from agents import function_tool
_PRICE_CENTS_PER_DAY = 25

def _amount_for(extra_days: int) -> int:
    if extra_days <= 0:
        raise ValueError('extra_days must be positive')
    return extra_days * _PRICE_CENTS_PER_DAY

@function_tool
def purchase_log_retention_upgrade(project_id: str, extra_days: int, customer_id: str) -> str:
    amount = _amount_for(extra_days)
    intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, off_session=True, metadata={'project_id': project_id, 'extra_days': str(extra_days)})
    return f'Charged {amount} cents, status {intent.status}, id {intent.id}'

import sqlite3
_DB = 'travel.db'

def move_booking_to_archive(booking_id: str) -> dict:
    if not booking_id or not booking_id.strip():
        return {'ok': False, 'error': 'booking_id is required'}
    conn = sqlite3.connect(_DB)
    try:
        row = conn.execute('SELECT status FROM bookings WHERE id = ?', (booking_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'booking not found'}
        if row[0] != 'completed':
            return {'ok': False, 'error': 'only completed bookings can be archived'}
        conn.execute('INSERT INTO bookings_archive SELECT * FROM bookings WHERE id = ?', (booking_id,))
        conn.execute('DELETE FROM bookings WHERE id = ?', (booking_id,))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'booking_id': booking_id, 'archived': True}

