import requests
import stripe
PRICE_PER_TAPE_CENTS = 450
VAULT_API = 'https://api.tapevault.example.com/v1/pickups'

def _charge(customer_id, count):
    return stripe.PaymentIntent.create(amount=PRICE_PER_TAPE_CENTS * count, currency='usd', customer=customer_id, confirm=True, off_session=True, description='Offsite tape shipment')

@tool
def order_offsite_tape_shipment(customer_id: str, tape_ids: list, pickup_address: str) -> dict:
    intent = _charge(customer_id, len(tape_ids))
    resp = requests.post(VAULT_API, json={'tapes': tape_ids, 'address': pickup_address, 'payment': intent.id}, timeout=30)
    resp.raise_for_status()
    return {'payment_id': intent.id, 'pickup': resp.json()}

import requests
import stripe
PRICE_PER_TAPE_CENTS = 450
VAULT_API = 'https://api.tapevault.example.com/v1/pickups'

def _charge(customer_id, count):
    return stripe.PaymentIntent.create(amount=PRICE_PER_TAPE_CENTS * count, currency='usd', customer=customer_id, confirm=True, off_session=True, description='Offsite tape shipment')

@tool
def order_offsite_tape_shipment(customer_id: str, tape_ids: list, pickup_address: str) -> dict:
    intent = _charge(customer_id, len(tape_ids))
    resp = requests.post(VAULT_API, json={'tapes': tape_ids, 'address': pickup_address, 'payment': intent.id}, timeout=30)
    resp.raise_for_status()
    return {'payment_id': intent.id, 'pickup': resp.json()}

import sqlite3
from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('lms')

@dataclass
class DeletePostResult:
    post_id: int
    deleted_posts: int

@mcp.tool()
def delete_course_discussion_post(post_id: int) -> DeletePostResult:
    connection = sqlite3.connect('lms.db')
    with connection:
        cursor = connection.execute('DELETE FROM discussion_posts WHERE id = ? OR parent_post_id = ?', (post_id, post_id))
    connection.close()
    return DeletePostResult(post_id=post_id, deleted_posts=cursor.rowcount)

import shutil
from pathlib import Path
from agents import function_tool

@function_tool
def move_repository_directory(source_path: str, destination_path: str) -> str:
    src = Path(source_path).expanduser().resolve()
    dst = Path(destination_path).expanduser().resolve()
    if not (src / '.git').exists():
        raise ValueError(f'{src} is not a git repository')
    if dst.exists():
        raise FileExistsError(f'{dst} already exists')
    dst.parent.mkdir(parents=True, exist_ok=True)
    moved = shutil.move(str(src), str(dst))
    return str(moved)

import os
import requests
from agents import function_tool
_BASE_URL = os.environ.get('FLIGHT_API_URL', 'https://api.flights.example.com/v2')
_API_KEY = os.environ.get('FLIGHT_API_KEY', '')

def _parse_offer(offer):
    first_segment = offer['segments'][0]
    last_segment = offer['segments'][-1]
    return {'offer_id': offer['id'], 'airline': first_segment['carrier'], 'departs': first_segment['departure_time'], 'arrives': last_segment['arrival_time'], 'stops': len(offer['segments']) - 1, 'duration_minutes': offer['duration_minutes'], 'price': float(offer['total_price']), 'currency': offer['currency']}

@function_tool
def search_flight_fares(origin: str, destination: str, departure_date: str, adults: int=1, cabin: str='ECONOMY') -> str:
    params = {'origin': origin.upper(), 'destination': destination.upper(), 'date': departure_date, 'adults': adults, 'cabin': cabin.upper(), 'max_results': 10}
    headers = {'Authorization': f'Bearer {_API_KEY}'}
    response = requests.get(f'{_BASE_URL}/offers', params=params, headers=headers, timeout=20)
    response.raise_for_status()
    payload = response.json()
    offers = [_parse_offer(o) for o in payload.get('offers', [])]
    offers.sort(key=lambda o: o['price'])
    lines = [f"{len(offers)} offers from {params['origin']} to {params['destination']} on {departure_date}"]
    for o in offers:
        lines.append(f"{o['offer_id']}: {o['airline']} {o['departs']} -> {o['arrives']}, {o['stops']} stops, {o['duration_minutes']} min, {o['price']:.2f} {o['currency']}")
    return '\n'.join(lines)

