import stripe

def buy_gpu_hours_for_sweep(team_id: str, gpu_hours: int, price_per_hour_cents: int):
    amount = gpu_hours * price_per_hour_cents
    intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=team_id, confirm=True, off_session=True, description=f'{gpu_hours} GPU hours for sweep', metadata={'gpu_hours': gpu_hours})
