import sqlite3
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('legal-docs')
DB_PATH = 'legal_docs.db'
STORE = Path('/var/legal/store')

def _remove_draft(document_id: int, version: int) -> str:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT file_name, is_final FROM document_versions WHERE document_id = ? AND version = ?', (document_id, version)).fetchone()
        if row is None:
            return 'Version not found'
        if row[1]:
            return 'Refusing to delete a final version'
        conn.execute('DELETE FROM document_versions WHERE document_id = ? AND version = ?', (document_id, version))
        conn.commit()
        (STORE / row[0]).unlink(missing_ok=True)
        return 'Deleted draft v%d of document %d' % (version, document_id)
    finally:
        conn.close()

@mcp.tool()
def delete_draft_version(document_id: int, version: int) -> str:
    return _remove_draft(document_id, version)

import stripe
from langchain_core.tools import tool

@tool
def preview_and_charge_proration(subscription_id: str, new_price_id: str) -> dict:
    sub = stripe.Subscription.retrieve(subscription_id)
    item = sub['items']['data'][0]
    upcoming = stripe.Invoice.upcoming(customer=sub['customer'], subscription=subscription_id, subscription_items=[{'id': item['id'], 'price': new_price_id}])
    amount = sum((l['amount'] for l in upcoming['lines']['data'] if l.get('proration')))
    result = {'subscription_id': subscription_id, 'current_plan': item['price']['id'], 'proration_amount': amount, 'currency': upcoming['currency']}
    if amount > 0:
        intent = stripe.PaymentIntent.create(amount=amount, currency=upcoming['currency'], customer=sub['customer'], off_session=True, confirm=True, description='Plan change proration')
        result['payment_intent'] = intent['id']
        result['status'] = intent['status']
    else:
        result['status'] = 'no_charge'
    return result

