def _build_message(rows, from_id, to_id):
    lines = [f'Moved {len(rows)} unfinished tasks from sprint {from_id} to sprint {to_id}:']
    lines += [f'- #{task_id}: {title}' for task_id, title in rows]
    return '\n'.join(lines)

@function_tool
def carry_over_tasks_and_notify(from_sprint_id: int, to_sprint_id: int) -> str:
    if from_sprint_id == to_sprint_id:
        return 'Source and target sprints are the same; nothing to do.'
    conn = sqlite3.connect(DB_PATH)
    try:
        rows = _move_unfinished(conn, from_sprint_id, to_sprint_id)
    finally:
        conn.close()
    if not rows:
        return f'No unfinished tasks found in sprint {from_sprint_id}.'
    resp = requests.post(WEBHOOK_URL, json={'text': _build_message(rows, from_sprint_id, to_sprint_id)}, timeout=10)
    if resp.status_code != 200:
        return f'Moved {len(rows)} tasks but Slack notification failed: {resp.status_code}'
    return f'Moved {len(rows)} tasks to sprint {to_sprint_id} and notified Slack.'

import sqlite3
DATABASE_PATH = 'support.db'

def get_ticket_history_summary(ticket_id: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        ticket_row = database_connection.execute('SELECT id, subject, status, owner_agent_id FROM tickets WHERE id = ?', (ticket_id,)).fetchone()
        if ticket_row is None:
            return {'error': 'Ticket not found'}
        comment_rows = database_connection.execute('SELECT author, body, created_at FROM comments WHERE ticket_id = ? ORDER BY created_at', (ticket_id,)).fetchall()
        return {'ticket': dict(ticket_row), 'comments': [dict(comment_row) for comment_row in comment_rows]}
    finally:
        database_connection.close()

import re
import subprocess
_SCRIPT = '/opt/billing/jobs/renew_subscriptions.py'
_DATE_RE = re.compile('^\\d{4}-\\d{2}-\\d{2}$')
_PLAN_RE = re.compile('^[a-z0-9_\\-]{2,40}$')

def run_renewal_batch(plan_code, billing_date, dry_run=True):
    if not _PLAN_RE.match(plan_code):
        return {'ok': False, 'error': 'invalid plan_code'}
    if not _DATE_RE.match(billing_date):
        return {'ok': False, 'error': 'billing_date must be YYYY-MM-DD'}
    cmd = ['python3', _SCRIPT, '--plan', plan_code, '--date', billing_date]
    if dry_run:
        cmd.append('--dry-run')
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=900, check=False)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': 'renewal job timed out', 'command': cmd}
    return {'ok': proc.returncode == 0, 'exit_code': proc.returncode, 'dry_run': dry_run, 'command': cmd, 'stdout': proc.stdout[-4000:], 'stderr': proc.stderr[-2000:]}

import os
import requests
_API_BASE = 'https://api.airline-partners.example/v2'
_API_KEY = os.environ.get('AIRLINE_PARTNER_KEY', '')

def check_airline_seat_availability(airline_code: str, flight_number: str, departure_date: str, loyalty_number: str='') -> dict:
    params = {'airline': airline_code.upper(), 'flight': flight_number, 'date': departure_date}
    if loyalty_number:
        params['loyalty'] = loyalty_number
    headers = {'Authorization': f'Bearer {_API_KEY}', 'Accept': 'application/json'}
    response = requests.get(f'{_API_BASE}/flights/availability', params=params, headers=headers, timeout=15)
    result = {'airline': params['airline'], 'flight': flight_number, 'date': departure_date, 'http_status': response.status_code}
    if response.status_code != 200:
        result['available'] = False
        result['error'] = response.text[:200]
        return result
    data = response.json()
    cabins = {}
    for cabin in data.get('cabins', []):
        cabins[cabin['name']] = cabin.get('seats_open', 0)
    result['cabins'] = cabins
    result['total_open'] = sum(cabins.values())
    result['available'] = result['total_open'] > 0
    result['loyalty_applied'] = bool(loyalty_number) and data.get('loyalty_recognized', False)
    return result

