import subprocess
from pathlib import Path

def wipe_wallet_keystore_and_run_shred(keystore_file_path: str, overwrite_pass_count: int=3) -> str:
    resolved_keystore_path = Path(keystore_file_path).expanduser().resolve()
    if not resolved_keystore_path.is_file():
        raise FileNotFoundError(f'Keystore file not found: {resolved_keystore_path}')
    if overwrite_pass_count < 1 or overwrite_pass_count > 35:
        raise ValueError('overwrite_pass_count must be between 1 and 35')
    shred_command_arguments = ['shred', '-n', str(overwrite_pass_count), '-u', '-z', str(resolved_keystore_path)]
    completed_shred_process = subprocess.run(shred_command_arguments, capture_output=True, text=True, timeout=120)
    if completed_shred_process.returncode != 0:
        raise RuntimeError(f'shred failed with code {completed_shred_process.returncode}: {completed_shred_process.stderr.strip()}')
    return f'Shredded and removed {resolved_keystore_path} using {overwrite_pass_count} passes'

import json
import time
from pathlib import Path

def prune_release_assets_and_update_index(release_dir: str, max_age_days: int):
    root = Path(release_dir)
    if not root.is_dir():
        return {'error': 'release directory not found'}
    if max_age_days < 1:
        return {'error': 'max_age_days must be at least 1'}
    index_path = root / 'index.json'
    if not index_path.is_file():
        return {'error': 'index.json missing'}
    index = json.loads(index_path.read_text())
    cutoff = time.time() - max_age_days * 86400
    removed = []
    kept = []
    for entry in index.get('assets', []):
        asset = root / entry['name']
        if asset.is_file() and asset.stat().st_mtime < cutoff:
            asset.unlink()
            removed.append(entry['name'])
        else:
            kept.append(entry)
    if not removed:
        return {'removed': [], 'message': 'nothing to prune'}
    index['assets'] = kept
    index_path.write_text(json.dumps(index, indent=2))
    return {'removed': removed, 'remaining': len(kept)}

