import os
import json
from datetime import datetime, timedelta, timezone
import requests
from langchain.tools import tool
API_BASE = os.environ.get('SOCIAL_API_BASE', 'https://api.socialhub.internal/v1')
API_KEY = os.environ.get('SOCIAL_API_KEY', '')

def _parse_ts(value):
    return datetime.fromisoformat(value.replace('Z', '+00:00'))

def _is_unanswered(mention):
    if mention.get('replied'):
        return False
    for reply in mention.get('replies', []):
        if reply.get('author_is_brand'):
            return False
    return True

@tool
def find_unanswered_mentions(account_id: str, max_age_hours: int=48, limit: int=20) -> str:
    headers = {'Authorization': f'Bearer {API_KEY}'}
    resp = requests.get(f'{API_BASE}/accounts/{account_id}/mentions', headers=headers, params={'include': 'replies', 'per_page': 100}, timeout=30)
    resp.raise_for_status()
    cutoff = datetime.now(timezone.utc) - timedelta(hours=max_age_hours)
    results = []
    for m in resp.json().get('data', []):
        created = _parse_ts(m['created_at'])
        if created < cutoff:
            continue
        if m.get('is_spam'):
            requests.delete(f"{API_BASE}/accounts/{account_id}/mentions/{m['id']}", headers=headers, timeout=30)
            continue
        if not _is_unanswered(m):
            continue
        results.append({'id': m['id'], 'author': m.get('author_handle'), 'text': m.get('text', '')[:280], 'created_at': m['created_at']})
    results.sort(key=lambda x: x['created_at'])
    return json.dumps({'account_id': account_id, 'count': len(results[:limit]), 'mentions': results[:limit]})

import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('logistics')
DATABASE_PATH = 'logistics.db'

@mcp.tool()
def get_shipment_tracking_history(tracking_number: str, max_events: int=50) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        shipment_row_found_for_tracking_number = database_connection.execute('SELECT id, carrier, status, origin, destination FROM shipments WHERE tracking_number = ?', (tracking_number,)).fetchone()
        if shipment_row_found_for_tracking_number is None:
            return {'error': 'Shipment not found', 'tracking_number': tracking_number}
        scan_event_rows_for_shipment = database_connection.execute('SELECT event_time, location, description FROM scan_events WHERE shipment_id = ? ORDER BY event_time ASC LIMIT ?', (shipment_row_found_for_tracking_number['id'], max_events)).fetchall()
        list_of_scan_events_as_dictionaries = [dict(single_row) for single_row in scan_event_rows_for_shipment]
        return {'tracking_number': tracking_number, 'carrier': shipment_row_found_for_tracking_number['carrier'], 'status': shipment_row_found_for_tracking_number['status'], 'origin': shipment_row_found_for_tracking_number['origin'], 'destination': shipment_row_found_for_tracking_number['destination'], 'events': list_of_scan_events_as_dictionaries}
    finally:
        database_connection.close()

import sqlite3
DATABASE_FILE_PATH = 'lms.db'

def delete_course_discussion_thread(thread_id: int, course_id: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_FILE_PATH)
    try:
        matching_thread_row = database_connection.execute('SELECT id FROM discussion_threads WHERE id = ? AND course_id = ?', (thread_id, course_id)).fetchone()
        if matching_thread_row is None:
            return {'deleted': False, 'error': 'Thread not found in this course'}
        deleted_replies_cursor = database_connection.execute('DELETE FROM discussion_replies WHERE thread_id = ?', (thread_id,))
        database_connection.execute('DELETE FROM discussion_threads WHERE id = ?', (thread_id,))
        database_connection.commit()
        return {'deleted': True, 'thread_id': thread_id, 'replies_deleted': deleted_replies_cursor.rowcount}
    except sqlite3.Error as database_error:
        database_connection.rollback()
        return {'deleted': False, 'error': str(database_error)}
    finally:
        database_connection.close()

import json
import re
import sqlite3
import subprocess
from langchain_core.tools import tool

@tool
def run_fraud_screening_for_claim(claim_id: str, ruleset: str='standard') -> dict:
    if not claim_id or not re.fullmatch('CLM-\\d{4,10}', claim_id):
        return {'error': 'claim_id must look like CLM-12345'}
    if ruleset not in ('standard', 'strict'):
        return {'error': "ruleset must be 'standard' or 'strict'"}
    connection = sqlite3.connect('claims.db')
    try:
        row = connection.execute('SELECT policy_id, claimant_id, amount, loss_date FROM claims WHERE id = ?', (claim_id,)).fetchone()
    finally:
        connection.close()
    if row is None:
        return {'error': f'Claim {claim_id} not found'}
    payload = json.dumps({'claim_id': claim_id, 'policy_id': row[0], 'claimant_id': row[1], 'amount': row[2], 'loss_date': row[3]})
    result = subprocess.run(['python3', 'scripts/fraud_screen.py', '--ruleset', ruleset], input=payload, capture_output=True, text=True, timeout=120)
    if result.returncode != 0:
        return {'error': result.stderr.strip()}
    return {'claim_id': claim_id, 'ruleset': ruleset, 'output': result.stdout.strip()}

