import sqlite3
from dataclasses import dataclass

@dataclass
class ArchiveResult:
    source: str
    destination: str
    rows_moved: int

def move_sqlite_table_rows_to_archive(db_path, table, archive_table, date_column, cutoff):
    for ident in (table, archive_table, date_column):
        if not ident.replace('_', '').isalnum():
            raise ValueError(f'Invalid identifier: {ident}')
    conn = sqlite3.connect(db_path)
    try:
        with conn:
            conn.execute(f'CREATE TABLE IF NOT EXISTS "{archive_table}" AS SELECT * FROM "{table}" WHERE 0')
            conn.execute(f'INSERT INTO "{archive_table}" SELECT * FROM "{table}" WHERE "{date_column}" < ?', (cutoff,))
            cur = conn.execute(f'DELETE FROM "{table}" WHERE "{date_column}" < ?', (cutoff,))
            moved = cur.rowcount
    finally:
        conn.close()
    return ArchiveResult(source=table, destination=archive_table, rows_moved=moved)

import sqlite3
import requests
from langchain.tools import tool
DATABASE_FILE_PATH = 'fitness.db'

@tool
def post_workout_to_club_webhook(workout_id: str, club_webhook_url: str) -> str:
    database_connection = sqlite3.connect(DATABASE_FILE_PATH)
    database_connection.row_factory = sqlite3.Row
    workout_row_from_database = database_connection.execute('SELECT user_name, activity_type, duration_minutes, calories_burned, distance_km FROM workouts WHERE id = ?', (workout_id,)).fetchone()
    database_connection.close()
    if workout_row_from_database is None:
        return 'Workout not found: ' + workout_id
    webhook_payload_dictionary = {'user': workout_row_from_database['user_name'], 'activity': workout_row_from_database['activity_type'], 'duration_minutes': workout_row_from_database['duration_minutes'], 'calories': workout_row_from_database['calories_burned'], 'distance_km': workout_row_from_database['distance_km']}
    webhook_http_response = requests.post(club_webhook_url, json=webhook_payload_dictionary, timeout=10)
    if webhook_http_response.status_code >= 400:
        return 'Club webhook rejected the post with status ' + str(webhook_http_response.status_code)
    return 'Workout ' + workout_id + ' posted to club feed'

import sqlite3
from dataclasses import dataclass
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('hr-recruiting')

@dataclass
class PurgeResult:
    candidate_id: int
    name: str
    role: str
    deleted: bool

@mcp.tool()
def purge_expired_candidate_record(candidate_id: int) -> PurgeResult:
    conn = sqlite3.connect('recruiting.db')
    with conn:
        row = conn.execute('SELECT name, role FROM candidates WHERE id = ?', (candidate_id,)).fetchone()
        if row is None:
            return PurgeResult(candidate_id, '', '', False)
        conn.execute('DELETE FROM applications WHERE candidate_id = ?', (candidate_id,))
        conn.execute('DELETE FROM candidates WHERE id = ?', (candidate_id,))
    conn.close()
    return PurgeResult(candidate_id, row[0], row[1], True)

