import re
import subprocess
from pathlib import Path
from langchain_core.tools import tool

@tool
def trigger_log_rotation(config_name: str, dry_run: bool=True) -> str:
    if not re.fullmatch('[A-Za-z0-9_.-]+', config_name):
        return 'error: invalid config name'
    cfg = Path('/etc/logrotate.d') / config_name
    if not cfg.is_file():
        return 'error: config not found'
    cmd = ['logrotate', '-f', str(cfg)]
    if dry_run:
        cmd = ['logrotate', '-d', str(cfg)]
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    return f'exit={proc.returncode}\n{proc.stdout}{proc.stderr}'

import sqlite3
DB_PATH = 'ticketing.db'

def revoke_box_office_staff_access(event_id: int, staff_id: int) -> dict:
    if event_id <= 0 or staff_id <= 0:
        return {'ok': False, 'error': 'invalid ids'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.execute('DELETE FROM event_staff WHERE event_id = ? AND staff_id = ?', (event_id, staff_id))
        if cur.rowcount == 0:
            return {'ok': False, 'error': 'staff assignment not found'}
        conn.execute('DELETE FROM staff_permissions WHERE event_id = ? AND staff_id = ?', (event_id, staff_id))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'event_id': event_id, 'staff_id': staff_id}

import sqlite3
DB_PATH = 'billing.db'

def _sum_payments(conn, invoice_id):
    row = conn.execute('SELECT COALESCE(SUM(amount_cents), 0) FROM payments WHERE invoice_id = ?', (invoice_id,)).fetchone()
    return row[0]

def get_invoice_balance_summary(invoice_id):
    conn = sqlite3.connect(DB_PATH)
    try:
        total = conn.execute('SELECT total_cents FROM invoices WHERE id = ?', (invoice_id,)).fetchone()[0]
        paid = _sum_payments(conn, invoice_id)
    finally:
        conn.close()
    return {'invoice_id': invoice_id, 'total_cents': total, 'paid_cents': paid, 'balance_cents': total - paid}

