import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('orders')
DATABASE_PATH = '/var/shop/orders.db'

@mcp.tool()
def get_order_summary(order_id: str) -> dict:
    connection = sqlite3.connect(DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    try:
        order_row = connection.execute('SELECT id, status, customer_email, created_at FROM orders WHERE id = ?', (order_id,)).fetchone()
        if order_row is None:
            return {'found': False, 'order_id': order_id}
        item_rows = connection.execute('SELECT sku, name, quantity, unit_price_cents FROM order_items WHERE order_id = ?', (order_id,)).fetchall()
    finally:
        connection.close()
    items = [dict(row) for row in item_rows]
    total_cents = sum((item['quantity'] * item['unit_price_cents'] for item in items))
    result = {'found': True, 'order_id': order_row['id'], 'status': order_row['status'], 'customer_email': order_row['customer_email'], 'created_at': order_row['created_at'], 'items': items, 'total_cents': total_cents}
    return result

import sqlite3
from dataclasses import dataclass
from agents import function_tool
DB_PATH = 'accounts.db'

@dataclass
class DeleteResult:
    user_id: int
    deleted: bool
    sessions_removed: int
    profiles_removed: int
    message: str

@function_tool
def delete_user_account(user_id: int) -> DeleteResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute('SELECT id FROM users WHERE id = ?', (user_id,))
        if cur.fetchone() is None:
            return DeleteResult(user_id, False, 0, 0, 'user not found')
        cur.execute('DELETE FROM sessions WHERE user_id = ?', (user_id,))
        sessions = cur.rowcount
        cur.execute('DELETE FROM profiles WHERE user_id = ?', (user_id,))
        profiles = cur.rowcount
        cur.execute('DELETE FROM users WHERE id = ?', (user_id,))
        removed = cur.rowcount > 0
        conn.commit()
        return DeleteResult(user_id, removed, sessions, profiles, 'account deleted' if removed else 'nothing deleted')
    except sqlite3.Error as exc:
        conn.rollback()
        return DeleteResult(user_id, False, 0, 0, f'database error: {exc}')
    finally:
        conn.close()

import os
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('ci-admin')
CI_API_BASE_URL = os.environ.get('CI_API_BASE_URL', 'https://ci.example.com/api/v4')
CI_API_HEADERS = {'PRIVATE-TOKEN': os.environ.get('CI_ADMIN_TOKEN', '')}

@mcp.tool()
def grant_pipeline_deploy_role(project_id: int, user_id: int) -> dict:
    membership_lookup_response = requests.get(f'{CI_API_BASE_URL}/projects/{project_id}/members/{user_id}', headers=CI_API_HEADERS, timeout=30)
    previous_role_name = None
    if membership_lookup_response.status_code == 200:
        previous_role_name = membership_lookup_response.json().get('role')
    role_update_response = requests.put(f'{CI_API_BASE_URL}/projects/{project_id}/members/{user_id}', headers=CI_API_HEADERS, json={'role': 'deployer'}, timeout=30)
    role_update_response.raise_for_status()
    return {'previous_role': previous_role_name, 'new_role': 'deployer'}

