import os
import subprocess
import requests
API_BASE = 'https://git.internal.example.com/api/v1'
HEADERS = {'Authorization': 'Bearer ' + os.environ.get('GIT_ADMIN_TOKEN', '')}

def _run_cache_cleanup(owner: str, repo: str, username: str) -> int:
    proc = subprocess.run(['/usr/local/bin/purge_git_cache.sh', owner, repo, username], capture_output=True, text=True, timeout=60)
    return proc.returncode

def remove_collaborator_and_revoke_tokens(owner: str, repo: str, username: str) -> dict:
    result = {'collaborator_removed': False, 'tokens_deleted': 0}
    base = f'{API_BASE}/repos/{owner}/{repo}'
    resp = requests.delete(f'{base}/collaborators/{username}', headers=HEADERS, timeout=30)
    result['collaborator_removed'] = resp.status_code == 204
    tokens = requests.get(f'{base}/deploy_tokens', headers=HEADERS, timeout=30).json()
    for token in tokens:
        if token.get('created_by') == username:
            r = requests.delete(f"{base}/deploy_tokens/{token['id']}", headers=HEADERS, timeout=30)
            if r.status_code == 204:
                result['tokens_deleted'] += 1
    result['cache_cleanup_exit_code'] = _run_cache_cleanup(owner, repo, username)
    return result

import hashlib
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path

@dataclass
class DuplicateReport:
    groups: list = field(default_factory=list)
    wasted_bytes: int = 0
    files_scanned: int = 0

def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()

def find_duplicate_files(directory: str, min_size_bytes: int=1) -> DuplicateReport:
    root = Path(directory).expanduser()
    by_size = defaultdict(list)
    report = DuplicateReport()
    for item in root.rglob('*'):
        if item.is_file() and (not item.is_symlink()):
            size = item.stat().st_size
            report.files_scanned += 1
            if size >= min_size_bytes:
                by_size[size].append(item)
    for size, paths in by_size.items():
        if len(paths) < 2:
            continue
        by_hash = defaultdict(list)
        for p in paths:
            by_hash[_sha256(p)].append(str(p))
        for digest, same in by_hash.items():
            if len(same) > 1:
                report.groups.append({'hash': digest, 'size': size, 'files': sorted(same)})
                report.wasted_bytes += size * (len(same) - 1)
    return report

