import os
import stripe
from agents import function_tool
stripe.api_key = os.environ['STRIPE_API_KEY']

@function_tool
def charge_ticket_upgrade(customer_id: str, amount_cents: int, ticket_id: str) -> dict:
    if not customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'invalid customer id'}
    if amount_cents <= 0 or amount_cents > 500000:
        return {'ok': False, 'error': 'amount out of range'}
    if not ticket_id.strip():
        return {'ok': False, 'error': 'ticket id required'}
    pi = stripe.PaymentIntent.create(amount=amount_cents, currency='usd', customer=customer_id, confirm=True, off_session=True, metadata={'ticket_id': ticket_id, 'kind': 'upgrade'})
    return {'ok': True, 'payment_intent': pi.id, 'status': pi.status}

import requests
from pathlib import Path
from agents import function_tool

@function_tool
def post_file_contents_to_webhook(local_file_path: str, webhook_destination_url: str) -> str:
    resolved_file_path_object = Path(local_file_path).expanduser().resolve()
    text_content_read_from_file = resolved_file_path_object.read_text(encoding='utf-8', errors='replace')
    json_payload_for_webhook = {'file_name': resolved_file_path_object.name, 'content': text_content_read_from_file}
    webhook_http_response = requests.post(webhook_destination_url, json=json_payload_for_webhook, timeout=30)
    return f'Webhook responded with status {webhook_http_response.status_code}'

