import os
import subprocess
from langchain.tools import tool

@tool
def scan_file_for_viruses(file_path: str) -> str:
    if not file_path or not file_path.strip():
        return 'Error: file_path is required.'
    absolute_path = os.path.abspath(os.path.expanduser(file_path))
    if not os.path.exists(absolute_path):
        return f'Error: file does not exist: {absolute_path}'
    if not os.path.isfile(absolute_path):
        return f'Error: not a regular file: {absolute_path}'
    completed_scan = subprocess.run(['clamscan', '--no-summary', absolute_path], capture_output=True, text=True, timeout=300)
    return completed_scan.stdout.strip() or completed_scan.stderr.strip()

import stripe
from agents import function_tool
from ci_billing import billing_client
PRICE_CENTS_PER_MINUTE = 1

@function_tool
def buy_ci_minutes_for_repo(repo_name: str, minutes: int, customer_id: str) -> dict:
    if '/' not in repo_name:
        return {'ok': False, 'error': 'repo_name must look like owner/name'}
    if minutes <= 0 or minutes % 500 != 0:
        return {'ok': False, 'error': 'minutes must be a positive multiple of 500'}
    remaining = billing_client.get_remaining_minutes(repo_name)
    intent = stripe.PaymentIntent.create(amount=minutes * PRICE_CENTS_PER_MINUTE, currency='usd', customer=customer_id, confirm=True, off_session=True, metadata={'repo': repo_name, 'minutes': minutes})
    return {'ok': intent.status == 'succeeded', 'previous_minutes': remaining, 'charged_cents': intent.amount, 'payment_id': intent.id}

import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('smart-home')
DB_PATH = '/var/lib/smarthome/registry.db'

@mcp.tool()
def move_device_to_room(device_id: str, target_room: str) -> dict:
    device_id = (device_id or '').strip()
    target_room = (target_room or '').strip().lower()
    if not device_id:
        return {'ok': False, 'error': 'device_id is required'}
    if not target_room:
        return {'ok': False, 'error': 'target_room is required'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT room FROM devices WHERE id = ?', (device_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'device not found'}
        if row[0] == target_room:
            return {'ok': False, 'error': 'device already in that room'}
        exists = conn.execute('SELECT 1 FROM rooms WHERE name = ?', (target_room,)).fetchone()
        if exists is None:
            return {'ok': False, 'error': 'target room does not exist'}
        conn.execute('UPDATE devices SET room = ? WHERE id = ?', (target_room, device_id))
        conn.commit()
    finally:
        conn.close()
    return {'ok': True, 'device_id': device_id, 'from': row[0], 'to': target_room}

