import sqlite3
from langchain_core.tools import tool
ZONE_DB = '/var/lib/dnsmgr/zones.db'

@tool
def set_record_ttl(zone: str, name: str, record_type: str, ttl: int) -> str:
    if not zone or not zone.strip():
        return 'error: zone is required'
    if not name or not name.strip():
        return 'error: name is required'
    rtype = record_type.upper().strip()
    if rtype not in {'A', 'AAAA', 'CNAME', 'MX', 'TXT', 'NS', 'SRV'}:
        return 'error: unsupported record type'
    if not isinstance(ttl, int) or ttl < 60 or ttl > 86400:
        return 'error: ttl must be between 60 and 86400'
    conn = sqlite3.connect(ZONE_DB)
    try:
        cur = conn.execute('UPDATE records SET ttl = ? WHERE zone = ? AND name = ? AND type = ?', (ttl, zone.strip().lower(), name.strip().lower(), rtype))
        conn.commit()
    finally:
        conn.close()
    if cur.rowcount == 0:
        return 'error: record not found'
    return f'updated {cur.rowcount} record(s) to ttl {ttl}'

import os
import stripe
from agents import function_tool
stripe.api_key = os.environ['STRIPE_API_KEY']
RATES = {'basic': 500, 'premium': 1200, 'spotlight': 2500}

@function_tool
def charge_listing_promotion_fee(mls_number: str, customer_id: str, days: int, tier: str='basic') -> dict:
    if days < 1 or days > 30:
        return {'error': 'days must be between 1 and 30'}
    t = tier.lower()
    if t not in RATES:
        return {'error': f"unknown tier '{tier}'"}
    if not customer_id.startswith('cus_'):
        return {'error': 'invalid customer_id'}
    amt = RATES[t] * days
    if days >= 14:
        amt = int(amt * 0.9)
    key = f'promo-{mls_number}-{customer_id}-{t}-{days}'
    try:
        cust = stripe.Customer.retrieve(customer_id)
        pm = cust.get('invoice_settings', {}).get('default_payment_method')
        if not pm:
            return {'error': 'customer has no default payment method'}
        pi = stripe.PaymentIntent.create(amount=amt, currency='usd', customer=customer_id, payment_method=pm, off_session=True, confirm=True, description=f'{t} promotion for {mls_number} ({days} days)', metadata={'mls_number': mls_number, 'tier': t, 'days': days}, idempotency_key=key)
    except stripe.error.CardError as e:
        return {'error': f'card declined: {e.user_message}'}
    except stripe.error.StripeError as e:
        return {'error': str(e)}
    return {'payment_intent': pi.id, 'status': pi.status, 'amount_cents': amt}

