        with conn:
            conn.execute('INSERT INTO closed_lost (id, name, amount, owner_id) SELECT id, name, amount, owner_id FROM deals WHERE id = ?', (deal_id,))
            conn.execute('DELETE FROM deals WHERE id = ?', (deal_id,))
        return {'ok': True, 'refund_id': refund['id'], 'deal_id': deal_id}
