def update_course_lesson_content(lesson_id: int, new_title: str, new_body_text: str, new_duration_minutes: int) -> dict:
    database_connection = sqlite3.connect(LMS_DATABASE_PATH)
    try:
        current_timestamp_iso_string = datetime.now(timezone.utc).isoformat()
        update_cursor_result = database_connection.execute('UPDATE lessons SET title = ?, body_text = ?, duration_minutes = ?, updated_at = ? WHERE id = ?', (new_title.strip(), new_body_text, new_duration_minutes, current_timestamp_iso_string, lesson_id))
        number_of_rows_changed = update_cursor_result.rowcount
        database_connection.commit()
    finally:
        database_connection.close()
    if number_of_rows_changed == 0:
        return {'updated': False, 'error': 'Lesson not found', 'lesson_id': lesson_id}
    return {'updated': True, 'lesson_id': lesson_id, 'updated_at': current_timestamp_iso_string}

import json
import shutil
from datetime import date, datetime
from pathlib import Path
from langchain_core.tools import tool

@tool
def archive_past_reservation_files(src_dir: str, archive_dir: str, cutoff_date: str='') -> dict:
    s = Path(src_dir)
    a = Path(archive_dir)
    if not s.is_dir():
        return {'error': 'source folder not found', 'moved': 0}
    if cutoff_date:
        try:
            c = datetime.strptime(cutoff_date, '%Y-%m-%d').date()
        except ValueError:
            return {'error': 'bad cutoff_date', 'moved': 0}
    else:
        c = date.today()
    moved = []
    kept = 0
    bad = []
    for p in sorted(s.glob('*.json')):
        try:
            with p.open() as f:
                d = json.load(f)
            r = datetime.strptime(d['date'], '%Y-%m-%d').date()
        except (OSError, ValueError, KeyError):
            bad.append(p.name)
            continue
        if r >= c:
            kept += 1
            continue
        t = a / r.strftime('%Y-%m')
        t.mkdir(parents=True, exist_ok=True)
        dst = t / p.name
        if dst.exists():
            dst = t / (p.stem + '_dup' + p.suffix)
        shutil.move(str(p), str(dst))
        moved.append({'id': d.get('id'), 'to': str(dst)})
    return {'cutoff': c.isoformat(), 'moved': len(moved), 'kept': kept, 'unreadable': bad, 'files': moved}

