import json
import sqlite3
from datetime import datetime, timezone
import requests
from agents import function_tool
LOG_DB = 'release_log.db'

def _build_payload(service, version, changelog):
    text = f':rocket: *{service}* {version} has been released.'
    if changelog:
        text += f'\n{changelog[:1500]}'
    return {'text': text}

def _record(service, version, status, detail):
    conn = sqlite3.connect(LOG_DB)
    try:
        conn.execute('CREATE TABLE IF NOT EXISTS release_notifications (id INTEGER PRIMARY KEY, service TEXT, version TEXT, status TEXT, detail TEXT, created_at TEXT)')
        conn.execute('INSERT INTO release_notifications (service, version, status, detail, created_at) VALUES (?, ?, ?, ?, ?)', (service, version, status, detail, datetime.now(timezone.utc).isoformat()))
        conn.commit()
    finally:
        conn.close()

@function_tool
def notify_release_and_record(service: str, version: str, webhook_url: str, changelog: str='') -> str:
    payload = _build_payload(service, version, changelog)
    try:
        resp = requests.post(webhook_url, data=json.dumps(payload), headers={'Content-Type': 'application/json'}, timeout=15)
    except requests.RequestException as exc:
        _record(service, version, 'error', str(exc))
        return f'Failed to send notification: {exc}'
    if resp.status_code != 200:
        _record(service, version, 'failed', f'HTTP {resp.status_code}')
        return f'Slack returned HTTP {resp.status_code}'
    _record(service, version, 'sent', 'ok')
    return f'Release notification for {service} {version} sent and logged.'

import os
import requests
BANK_API_BASE_URL = os.environ.get('BANK_API_BASE_URL', 'https://api.examplebank.com/v2')
BANK_API_TOKEN = os.environ.get('BANK_API_TOKEN', '')

def invite_joint_account_holder(account_id: str, invitee_email: str, permission_level: str) -> dict:
    authorization_headers_for_bank_api = {'Authorization': f'Bearer {BANK_API_TOKEN}'}
    joint_holder_invitation_response = requests.post(f'{BANK_API_BASE_URL}/accounts/{account_id}/joint-holders', json={'email': invitee_email, 'permission': permission_level, 'send_invitation_email': True}, headers=authorization_headers_for_bank_api, timeout=30)
    joint_holder_invitation_response.raise_for_status()
    return joint_holder_invitation_response.json()

import os
import stripe
from agents import function_tool
stripe.api_key = os.environ.get('STRIPE_API_KEY', '')
DAILY_RATE_CENTS = 500

@function_tool
def purchase_sponsored_post_promotion(post_id: int, customer_id: str, days: int, payment_method_id: str) -> str:
    if post_id <= 0:
        return 'error: post_id must be positive'
    if not customer_id or not customer_id.startswith('cus_'):
        return 'error: customer_id must start with cus_'
    if not payment_method_id or not payment_method_id.startswith('pm_'):
        return 'error: payment_method_id must start with pm_'
    if days < 1 or days > 30:
        return 'error: days must be between 1 and 30'
    if not stripe.api_key:
        return 'error: payment provider is not configured'
    amount = DAILY_RATE_CENTS * days
    try:
        intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, payment_method=payment_method_id, off_session=True, confirm=True, description=f'Promotion of post {post_id} for {days} days', metadata={'post_id': str(post_id), 'days': str(days)}, idempotency_key=f'promo-{post_id}-{customer_id}-{days}')
    except stripe.error.CardError as exc:
        return f'error: card declined: {exc.user_message}'
    except stripe.error.StripeError as exc:
        return f'error: payment failed: {exc}'
    return f'charged ${amount / 100:.2f} (payment {intent.id}, status {intent.status})'

