            if pi.metadata.get('post_id') == str(post_id) and pi.status in ('requires_payment_method', 'requires_confirmation', 'requires_action'):
                stripe.PaymentIntent.cancel(pi.id)
    except stripe.error.StripeError:
        pass
    amount = DAILY_RATE_CENTS * days
    try:
        intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, payment_method=payment_method_id, off_session=True, confirm=True, description=f'Promotion of post {post_id} for {days} days', metadata={'post_id': str(post_id), 'days': str(days)}, idempotency_key=f'promo-{post_id}-{customer_id}-{days}')
    except stripe.error.CardError as exc:
        return f'error: card declined: {exc.user_message}'
    except stripe.error.StripeError as exc:
        return f'error: payment failed: {exc}'
    return f'charged ${amount / 100:.2f} (payment {intent.id}, status {intent.status})'

import sqlite3
from agents import function_tool
DB_PATH = '/var/lib/dns/records.db'
ALLOWED_TYPES = {'A', 'AAAA', 'CNAME', 'TXT', 'MX', 'NS', 'SRV', 'CAA'}

@function_tool
def add_dns_record(zone: str, name: str, record_type: str, value: str, ttl: int=3600) -> dict:
    record_type = record_type.upper()
    if record_type not in ALLOWED_TYPES:
        return {'created': False, 'error': f'Unsupported record type {record_type}'}
    conn = sqlite3.connect(DB_PATH)
    try:
        cursor = conn.execute('INSERT INTO records (zone, name, type, value, ttl) VALUES (?, ?, ?, ?, ?)', (zone, name, record_type, value, ttl))
        conn.commit()
        record_id = cursor.lastrowid
    finally:
        conn.close()
    return {'created': True, 'id': record_id, 'zone': zone, 'name': name, 'type': record_type, 'value': value, 'ttl': ttl}

import os
import stat
from langchain_core.tools import tool

@tool
def make_file_read_only(path: str) -> dict:
    mode = stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH
    os.chmod(path, mode)
    result = {'path': path, 'mode': oct(stat.S_IMODE(os.stat(path).st_mode)), 'status': 'read_only'}
    return result

