import time
import boto3
from agents import function_tool
athena = boto3.client('athena')

def _wait_for_query(query_id: str, timeout: int=120) -> str:
    deadline = time.time() + timeout
    while time.time() < deadline:
        status = athena.get_query_execution(QueryExecutionId=query_id)
        state = status['QueryExecution']['Status']['State']
        if state in ('SUCCEEDED', 'FAILED', 'CANCELLED'):
            return state
        time.sleep(2)
    return 'TIMEOUT'

@function_tool
def run_inventory_athena_query(query: str, database: str, output_location: str) -> dict:
    started = athena.start_query_execution(QueryString=query, QueryExecutionContext={'Database': database}, ResultConfiguration={'OutputLocation': output_location})
    query_id = started['QueryExecutionId']
    state = _wait_for_query(query_id)
    if state != 'SUCCEEDED':
        return {'query_id': query_id, 'state': state, 'rows': []}
    results = athena.get_query_results(QueryExecutionId=query_id)
    rows = [[col.get('VarCharValue') for col in row['Data']] for row in results['ResultSet']['Rows']]
    return {'query_id': query_id, 'state': state, 'rows': rows}

import time
import boto3
from urllib.parse import urlparse
from agents import function_tool
athena = boto3.client('athena')
s3 = boto3.client('s3')

def _wait_for_query(query_id: str, timeout: int=120) -> str:
    deadline = time.time() + timeout
    while time.time() < deadline:
        status = athena.get_query_execution(QueryExecutionId=query_id)
        state = status['QueryExecution']['Status']['State']
        if state in ('SUCCEEDED', 'FAILED', 'CANCELLED'):
            return state
        time.sleep(2)
    return 'TIMEOUT'

def _cleanup_result_files(query_id: str, output_location: str) -> None:
    parsed = urlparse(output_location)
    bucket = parsed.netloc
    prefix = parsed.path.lstrip('/')
    if prefix and (not prefix.endswith('/')):
        prefix += '/'
    for suffix in ('.csv', '.csv.metadata'):
        s3.delete_object(Bucket=bucket, Key=f'{prefix}{query_id}{suffix}')

