import sqlite3
import subprocess
DB_PATH = 'lms.db'
SYNC_SCRIPT = '/opt/lms/scripts/sync_roster.py'
_ALLOWED_ROLES = {'ta', 'instructor'}

def run_enrollment_sync_and_grant_instructor_role(course_id: str, user_id: str, role: str) -> str:
    if not course_id or not course_id.replace('-', '').replace('_', '').isalnum():
        return 'error: invalid course_id'
    if not user_id:
        return 'error: user_id is required'
    if role not in _ALLOWED_ROLES:
        return "error: role must be 'ta' or 'instructor'"
    proc = subprocess.run(['python3', SYNC_SCRIPT, '--course', course_id], capture_output=True, text=True, timeout=300)
    if proc.returncode != 0:
        return 'error: roster sync failed: ' + proc.stderr.strip()[:200]
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT 1 FROM enrollments WHERE course_id = ? AND user_id = ?', (course_id, user_id)).fetchone()
        if row is None:
            return 'error: user is not on the course roster'
        conn.execute('UPDATE enrollments SET role = ? WHERE course_id = ? AND user_id = ?', (role, course_id, user_id))
        conn.commit()
    finally:
        conn.close()
    return f'synced roster and set {user_id} to {role} on {course_id}'

import shutil
import time
from pathlib import Path
import requests
RECORDINGS_DIR = Path('/var/smarthome/recordings')
ARCHIVE_DIR = Path('/var/smarthome/archive')
WEBHOOK_URL = 'https://monitor.home.local/api/webhooks/clip-archived'
RETENTION_DAYS = 30

def _notify(camera_id, dest):
    payload = {'camera_id': camera_id, 'archived_path': str(dest), 'size': dest.stat().st_size}
    resp = requests.post(WEBHOOK_URL, json=payload, timeout=10)
    resp.raise_for_status()
    return resp.status_code

def archive_and_report_camera_clip(clip_name: str, camera_id: str) -> dict:
    cutoff = time.time() - RETENTION_DAYS * 86400
    camera_archive = ARCHIVE_DIR / camera_id
    if camera_archive.is_dir():
        for old in camera_archive.iterdir():
            if old.is_file() and old.stat().st_mtime < cutoff:
                old.unlink()
    src = RECORDINGS_DIR / Path(clip_name).name
    if not src.exists():
        return {'ok': False, 'error': 'clip not found'}
    target_dir = ARCHIVE_DIR / camera_id
    target_dir.mkdir(parents=True, exist_ok=True)
    dest = target_dir / src.name
    shutil.move(str(src), str(dest))
    status = _notify(camera_id, dest)
    return {'ok': True, 'archived_to': str(dest), 'webhook_status': status}

