import re
import shutil
import subprocess
import tempfile
from contextlib import contextmanager
from pathlib import Path
from langchain_core.tools import tool
BANK_SCRIPT = '/opt/payroll/scripts/generate_bank_file.py'

@contextmanager
def _staging_lock(archive_path: Path, period: str):
    lock = archive_path / f'.{period}.lock'
    if lock.exists():
        raise RuntimeError(f'archive for {period} is already being processed')
    lock.touch()
    try:
        yield lock
    finally:
        lock.unlink(missing_ok=True)

@contextmanager
def _log_file(path: Path):
    handle = open(path, 'a', encoding='utf-8')
    try:
        yield handle
    finally:
        handle.close()

@tool
def archive_and_run_payroll_export(pay_period: str, export_dir: str, archive_dir: str) -> str:
    if not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', pay_period):
        return 'Error: pay_period must be YYYY-MM.'
    source = Path(export_dir) / f'payroll_{pay_period}.csv'
    if not source.is_file():
        return f'Error: export file not found: {source}'
    archive_path = Path(archive_dir)
    archive_path.mkdir(parents=True, exist_ok=True)
    target = archive_path / source.name
    if target.exists():
        return f'Error: {target} already exists.'
    try:
        with _staging_lock(archive_path, pay_period):
            shutil.move(str(source), str(target))
            with _log_file(archive_path / 'bank_file.log') as log:
                result = subprocess.run(['python3', BANK_SCRIPT, '--input', str(target)], stdout=log, stderr=subprocess.STDOUT, timeout=300)
    except (RuntimeError, OSError, subprocess.TimeoutExpired) as exc:
        return f'Error: {exc}'
    if result.returncode != 0:
        return f'Bank file script failed with exit code {result.returncode}; see bank_file.log.'
    return f'Archived to {target} and generated bank file.'

import sqlite3
import logging
log = logging.getLogger(__name__)
DB = 'warehouse.db'

def delete_discontinued_sku_records(skus, force=False):
    if not skus:
        return {'deleted': {}, 'skipped': []}
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    out = {'deleted': {}, 'skipped': []}
    try:
        for s in skus:
            row = c.execute('SELECT status FROM skus WHERE sku = ?', (s,)).fetchone()
            if row is None:
                out['skipped'].append({'sku': s, 'reason': 'unknown'})
                continue
            if row['status'] != 'discontinued':
                out['skipped'].append({'sku': s, 'reason': 'not discontinued'})
                continue
            n = c.execute('SELECT COALESCE(SUM(quantity), 0) FROM bin_stock WHERE sku = ?', (s,)).fetchone()[0]
            if n > 0 and (not force):
                out['skipped'].append({'sku': s, 'reason': f'{n} units on hand'})
                continue
            cnt = {}
            for t in ('bin_stock', 'lots', 'reorder_rules', 'skus'):
                cur = c.execute(f'DELETE FROM {t} WHERE sku = ?', (s,))
                cnt[t] = cur.rowcount
            out['deleted'][s] = cnt
            log.info('deleted sku %s: %s', s, cnt)
        c.commit()
    except sqlite3.Error:
        c.rollback()
        raise
    finally:
        c.close()
    return out

