import os
import tempfile
import requests
MAX_NOTES_CHARS = 2500

def _build_payload(repo_name, tag, release_notes, mention_group):
    notes = release_notes.strip()
    if len(notes) > MAX_NOTES_CHARS:
        notes = notes[:MAX_NOTES_CHARS].rstrip() + '\n... (truncated)'
    header = f'*{repo_name}* released `{tag}`'
    if mention_group:
        header = f'<!subteam^{mention_group}> {header}'
    release_url = f'https://github.com/{repo_name}/releases/tag/{tag}'
    return {'text': header, 'blocks': [{'type': 'section', 'text': {'type': 'mrkdwn', 'text': header}}, {'type': 'section', 'text': {'type': 'mrkdwn', 'text': notes}}, {'type': 'context', 'elements': [{'type': 'mrkdwn', 'text': f'<{release_url}|View release>'}]}]}

def _remove_draft_file(repo_name, tag):
    draft_name = f"{repo_name.replace('/', '_')}-{tag}.md"
    draft_path = os.path.join(tempfile.gettempdir(), 'release_drafts', draft_name)
    try:
        if os.path.isfile(draft_path):
            os.remove(draft_path)
    except OSError:
        pass

def post_release_announcement(webhook_url: str, repo_name: str, tag: str, release_notes: str, mention_group: str=None) -> dict:
    if not webhook_url.startswith('https://'):
        return {'ok': False, 'error': 'webhook_url must use https'}
    if '/' not in repo_name:
        return {'ok': False, 'error': 'repo_name must look like owner/name'}
    if not tag.strip():
        return {'ok': False, 'error': 'tag is required'}
    payload = _build_payload(repo_name, tag.strip(), release_notes, mention_group)
    try:
        response = requests.post(webhook_url, json=payload, timeout=15)
        response.raise_for_status()
    except requests.RequestException as exc:
        return {'ok': False, 'error': str(exc)}
    _remove_draft_file(repo_name, tag.strip())
    return {'ok': True, 'status_code': response.status_code, 'tag': tag, 'repo': repo_name}

import sqlite3
from dataclasses import dataclass
from typing import Optional
from langchain_core.tools import tool
DB = 'store.db'

@dataclass
class CreditResult:
    success: bool
    message: str
    new_balance: Optional[float] = None
    credit_id: Optional[int] = None

@tool
def issue_store_credit_for_return(order_id: int, customer_id: int, amount: float, note: str='') -> CreditResult:
    if amount <= 0:
        return CreditResult(False, 'Amount must be positive')
    cn = sqlite3.connect(DB)
    try:
        cur = cn.cursor()
        order = cur.execute('SELECT total FROM orders WHERE id = ? AND customer_id = ?', (order_id, customer_id)).fetchone()
        if order is None:
            return CreditResult(False, 'Order not found for this customer')
        done = cur.execute('SELECT COALESCE(SUM(amount), 0) FROM store_credits WHERE order_id = ?', (order_id,)).fetchone()[0]
        if done + amount > order[0]:
            return CreditResult(False, f'Credit would exceed order total of {order[0]:.2f}')
        cur.execute('INSERT INTO store_credits (order_id, customer_id, amount, note) VALUES (?, ?, ?, ?)', (order_id, customer_id, amount, note))
        cid = cur.lastrowid
        cur.execute('UPDATE customers SET credit_balance = credit_balance + ? WHERE id = ?', (amount, customer_id))
        bal = cur.execute('SELECT credit_balance FROM customers WHERE id = ?', (customer_id,)).fetchone()
        if bal is None:
            cn.rollback()
            return CreditResult(False, 'Customer not found')
        cn.commit()
        return CreditResult(True, 'Store credit issued', bal[0], cid)
    except sqlite3.Error as e:
        cn.rollback()
        return CreditResult(False, f'Database error: {e}')
    finally:
        cn.close()

