import sqlite3
from dataclasses import dataclass, field
from datetime import date
DATABASE_PATH = 'billing.db'

@dataclass
class PurgeResult:
    success: bool
    deleted_invoice_ids: list = field(default_factory=list)
    deleted_line_item_count: int = 0
    message: str = ''

def purge_draft_invoices(customer_id: str, older_than_date: str, max_deletions: int=100) -> PurgeResult:
    try:
        cutoff = date.fromisoformat(older_than_date)
    except ValueError:
        return PurgeResult(success=False, message='Invalid date format')
    if max_deletions <= 0:
        return PurgeResult(success=False, message='max_deletions must be positive')
    if cutoff > date.today():
        return PurgeResult(success=False, message='Cutoff date cannot be in the future')
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        cursor = connection.cursor()
        cursor.execute("SELECT id FROM invoices WHERE customer_id = ? AND status = 'draft' AND last_edited < ? ORDER BY last_edited LIMIT ?", (customer_id, cutoff.isoformat(), max_deletions))
        invoice_ids = [row[0] for row in cursor.fetchall()]
        if not invoice_ids:
            return PurgeResult(success=True, message='No matching drafts')
        placeholders = ','.join(('?' for _ in invoice_ids))
        cursor.execute(f'DELETE FROM invoice_shares WHERE invoice_id IN ({placeholders})', invoice_ids)
        cursor.execute(f'DELETE FROM invoice_access_tokens WHERE invoice_id IN ({placeholders})', invoice_ids)
        cursor.execute(f'DELETE FROM invoice_line_items WHERE invoice_id IN ({placeholders})', invoice_ids)
        line_item_count = cursor.rowcount
        cursor.execute(f'DELETE FROM invoices WHERE id IN ({placeholders})', invoice_ids)
        connection.commit()
        return PurgeResult(success=True, deleted_invoice_ids=invoice_ids, deleted_line_item_count=line_item_count, message='Deleted drafts')
    except sqlite3.Error as error:
        connection.rollback()
        return PurgeResult(success=False, message=str(error))
    finally:
        connection.close()

import sqlite3
from langchain_core.tools import tool
db = sqlite3.connect('tickets.db', check_same_thread=False)

@tool
def set_ticket_priority(ticket_id: int, priority: str) -> str:
    p = priority.lower()
    if p not in ('low', 'normal', 'high', 'urgent'):
        return 'Invalid priority'
    c = db.execute('UPDATE tickets SET priority = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', (p, ticket_id))
    db.commit()
    if c.rowcount == 0:
        return 'Ticket not found'
    return f'Ticket {ticket_id} priority set to {p}'

import sqlite3
import stripe
from agents import tool
DB_PATH = '/var/data/recruiting.db'
MAX_BONUS_USD = 5000

@tool
def pay_referral_bonus(applicant_id: str, referrer_customer_id: str, amount_usd: float) -> dict:
    if not applicant_id or not applicant_id.strip():
        return {'ok': False, 'error': 'applicant_id is required'}
    if not referrer_customer_id.startswith('acct_'):
        return {'ok': False, 'error': 'referrer_customer_id must be a connected account id'}
    if amount_usd <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    if amount_usd > MAX_BONUS_USD:
        return {'ok': False, 'error': f'amount exceeds limit of {MAX_BONUS_USD}'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT full_name, status, referrer_account FROM applicants WHERE id = ?', (applicant_id,)).fetchone()
    finally:
        conn.close()
    if row is None:
        return {'ok': False, 'error': 'applicant not found'}
    name, status, ref_acct = row
    if status != 'hired':
        return {'ok': False, 'error': f'applicant status is {status}, not hired'}
    if ref_acct != referrer_customer_id:
        return {'ok': False, 'error': 'referrer does not match the hire record'}
    transfer = stripe.Transfer.create(amount=int(round(amount_usd * 100)), currency='usd', destination=referrer_customer_id, description=f'Referral bonus for {name}', idempotency_key=f'referral-{applicant_id}')
    return {'ok': True, 'transfer_id': transfer.id, 'applicant': name, 'amount_usd': amount_usd}

import sqlite3
import stripe
DB_PATH = 'cms.db'

def refund_and_unpublish_paid_article(purchase_id: int, refund_cents: int) -> dict:
    if not isinstance(purchase_id, int) or purchase_id <= 0:
        return {'ok': False, 'error': 'purchase_id must be a positive integer'}
    if not isinstance(refund_cents, int) or refund_cents <= 0:
        return {'ok': False, 'error': 'refund_cents must be a positive integer'}
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute('SELECT payment_intent_id, amount_cents, status FROM purchases WHERE id = ?', (purchase_id,)).fetchone()
    if row is None:
        conn.close()
        return {'ok': False, 'error': 'purchase not found'}
    payment_intent_id, amount_cents, status = row
    if status == 'refunded':
        conn.close()
        return {'ok': False, 'error': 'purchase already refunded'}
    if refund_cents > amount_cents:
        conn.close()
        return {'ok': False, 'error': 'refund exceeds purchase amount'}
    refund = stripe.Refund.create(payment_intent=payment_intent_id, amount=refund_cents)
    with conn:
        conn.execute("UPDATE purchases SET status = 'refunded', refund_id = ? WHERE id = ?", (refund.id, purchase_id))
    conn.close()
    return {'ok': True, 'refund_id': refund.id}

